TLM.f("Sancti/05-26",{"officium":"S. Philippi Neri Confessoris","rule":["vide C5;","9 lectiones","Gloria"],"fallback":"Commune/C5","from":{"Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Rom 5:5"},{"k":"text","la":"Cáritas Dei diffúsa est in córdibus nostris per inhabitántem Spíritum ejus in nobis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps. 102:1"},{"k":"text","la":"Benedic, ánima mea, Dómino: et ómnia, quæ intra me sunt, nómini sancto ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Cáritas Dei diffúsa est in córdibus nostris per inhabitántem Spíritum ejus in nobis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui beátum Philíppum Confessórem tuum Sanctórum tuórum glória sublimásti: concéde propítius; ut, cujus sollemnitáte lætámur, ejus virtútum proficiámus exémplo."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 7:7-14"},{"k":"text","la":"Optávi, et datus est mihi sensus: et invocávi, et venit in me spíritus sapiéntiæ: et præpósui illam regnis et sédibus, et divítias nihil esse duxi in comparatióne illíus: nec comparávi illi lápidem pretiósum: quóniam omne aurum in comparatióne illíus arena est exígua, et tamquam lutum æstimábitur argéntum in conspéctu illíus. Super salútem et spéciem diléxi illam, et propósui pro luce habére illam: quóniam inexstinguíbile est lumen illíus. Venérunt autem mihi ómnia bona páriter cum illa, et innumerábilis honéstas per manus illíus, et lætátus sum in ómnibus: quóniam antecedébat me ista sapiéntia, et ignorábam, quóniam horum ómnium mater est. Quam sine fictióne dídici et sine invídia commúnico, et honestátem illíus non abscóndo. Infinítus enim thesáurus est homínibus: quo qui usi sunt, partícipes facti sunt amicítiæ Dei, propter disciplínæ dona commendáti."}],"Graduale":[{"k":"ref","la":"Ps 33:12; 33:6"},{"k":"text","la":"Veníte, fílii, audíte me: timórem Dómini docébo vos."},{"k":"text","la":"Accédite ad eum, et illuminámini: et fácies vestra? non confundántur. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Lam 1:18"},{"k":"text","la":"De excélso misit ignem in óssibus meis, et erudívit me. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Lam 1:13"},{"k":"text","la":"De excélso misit ignem in óssibus meis, et erudívit me. Allelúja"},{"k":"ref","la":"Ps 38:4"},{"k":"text","la":"Concáluit cor meum intra me: et in meditatióne mea exardéscet ignis. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:35-40"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Sint lumbi vestri præcíncti, et lucernæ ardéntes in mánibus vestris, et vos símiles homínibus exspectántibus dóminum suum, quando revertátur a núptiis: ut, cum vénerit et pulsáverit, conféstim apériant ei. Beáti servi illi, quos, cum vénerit dóminus, invénerit vigilántes: amen, dico vobis, quod præcínget se, et fáciet illos discúmbere, et tránsiens ministrábit illis. Et si vénerit in secúnda vigília, et si in tértia vigília vénerit, et ita invénerit, beáti sunt servi illi. Hoc autem scitóte, quóniam, si sciret paterfamílias, qua hora fur veníret, vigiláret útique, et non síneret pérfodi domum suam. Et vos estóte paráti, quia, qua hora non putátis, Fílius hóminis véniet."}],"Offertorium":[{"k":"ref","la":"Ps 118:32"},{"k":"text","la":"Viam mandatórum tuórum cucúrri, cum dilatásti cor meum. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Sacrifíciis præséntibus, quǽsumus, Dómine, inténde placatus: et præsta; ut illo nos igne Spíritus Sanctus inflámmet, quo beáti Phílippi cor mirabíliter penetrávit."},{"k":"macro","name":"Per Dominum eiusdem"}],"Communio":[{"k":"ref","la":"Ps 83:3"},{"k":"text","la":"Cor meum et caro mea exsultavérunt in Deum vivum. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Cœléstibus, Dómine, pasti delíciis: quǽsumus; ut beáti Philippi Confessóris tui méritis et imitatióne, semper eadem, per quæ veráciter vívimus, appetámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"38490f180990c279":{"t":"Rim 5, 5, Ps 102, 1\n(Rim 5, 5) Ljubav se Božja izlila u našim srcima po Duhu Svetom, koji stanuje u nama. <i>Aleluja</i>, <i>aleluja</i>.\n(Ps 102, 1) Blagoslivljaj, dušo moja, Gospodina! I sve što je u meni sveto ime njegovo.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Rim 5, 5) Ljubav se Božja izlila u našim srcima po Duhu Svetom, koji stanuje u nama, <i>aleluja</i>, <i>aleluja</i>.","v":"aleluia aleluia → ∅; aleluia aleluia → ∅","kn":"(Rim. 5, 5). Ljubav se Božja izlila u srcima našim., aleluja, po Duhu Svetom, koji nam je dan aleluja, aleluja: (Ps. 102, 1). Blagosivaj, dušo moja' Gospodina, i sve, što je u meni, sveto ime njegovo’. Slava Ocu . . . Ljubav . . . se« dijeli se prva tonzura,.. a onda se«, bez »Prignimo . , a tako i","knRef":"Kniewald 1942, str. 354–355 (snimka 178) (OCR)"},"7c4fcf9317e22fa3":{"t":"<i>Pomolimo se</i>.\nBože, koji si blaženog Filipa priznavaoca svoga uzvisio slavom svojih svetih, daj milostiv da se okoristimo kreposnim primjerom onoga kojega se svetkovini radujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si. bi. Filipa, priznavaoca svoga, U2V1S10 do slave svojih svetih, dopusti milostivo da napredujemo u kreposti slijedeći primjer onoga koga radosno slavimo, po G. n. ' str^ M3 ‘ iz Mise »Štiti me. st^^sJr^*^ blagdan sv. Tome Akvinca, Na stepemcama (Ps. 33, 12-16). Dođite, djeco, čujte me, učit ĆU vas strahu Gospodnjem. Približite se Sv. Beđa VčnerabiUs 27. V.","knRef":"Kniewald 1942, str. 580–581 (snimka 291) (OCR)"},"4234f6d249240914":{"t":"Mudr 7, 7-14\nČitanje knjige Mudrosti. Zaželio sam i dano mi je shvaćanje, molio sam i došao je u mene duh mudrosti koja mi je draža nego kraljevstva i prijestolja, a bogatstvo prema njoj nije ništa. Ne uspoređujem s njom dragi kamen, jer sve zlato prema njoj je kao sitan pijesak, a srebro je pored nje kao blato. Volim je više nego li zdravlje i ljepotu. Uzeo sam je kao svoje svjetlo što se ne može ugasiti. Zajedno s njom imam sva druga dobra, iz njezinih ruku. primam neizmjerno bogatstvo. Radujem se tome svemu, jer ova mudrost je moj vođa, a nisam znao, da je ona izvor sviju dobara. Naučio sam je bez himbe, i predajem je bez zavisti i ne sakrivam njezina blaga. Ona je neiscrpivo blago za sve ljude. Oni koji se njome služe postaju Božji prijatelji, preporučeni darovima nauke.","kn":"Čitanje Knjige mudrosti (7, 7-14). Želio sam pamet, i bila mi je udijeljena, zazvao sam, i došao je u me dah mudrosti, koja mi je bila draža od kraljevstva i prijestolja, i držao sam, da bogatstvo prema njoj nije ništa. Niti sam s njom poredio dragog kamenja, jer je sve zlato prema njoj kao malo pijeska, a srebro uz nju držim kao blato ^ Ljubio sam je više nego zdravlje i ljepotu i odlučio sam je uzeti za svoje svijetlo, koje se ne može ugaati. S njom su mi došla sva dobra i nebrojeno sam bo- gatstvo primio iz njezinih ruku: Veselio sam se svemu tomu, jer je ova mudrost bila mojim vođom, a nljesam znao, da je ona majka svih ovih dobara. Naučio sam je bez himbe, i predajem je bez zavisti, i ne sakrivam njezina bogatstva, jer je ona neiscrpivo blago za sve ljude. Koji se njom služe, postaju dionicima Božjega prijateljstva, preporučeni po darovima nauke.","knRef":"Kniewald 1942, str. 518–519 (snimka 260) (OCR)"},"b677316be1651bac":{"kn":"(Ps. 33, 12-16). Dođite, djeco, čujte me, učit ću vas strahu Gospodnjem. Približite se Gospodinu, pa ćete od radosti zasjati i lica se vaša ne će zastidjeti.\nAleluja, aleluja. Iz visina je poslao oganj u kosti moje i poučio me je, aleluja.","knRef":"Kniewald 1942, str. 580-581"},"52bdf7255321563a":{"t":"Lk 12, 35-40\nSlijedi sveto Evanđelje po Luki. U ono vrijeme Isus reče svojim učenicima: Neka budu opasani vaši bokovi i upaljene svjetiljke u vašim rukama, a vi budite slični slugama koji očekuju svojega gospodara, kada se vraća sa svadbe, da mu smjesta otvore vrata, čim dođe i pokuca. Blago onim slugama koje gospodar kada dođe nađe budne! Uvjeravam vas, da će se sam pripasati, narediti im da sjednu za stol i poslužiti ih. Blago tim slugama, ako ih nađe tako došao on bilo o drugoj, ili o trećoj straži. Pazite: Kada bi domaćin znao u koji čas dolazi tat, ne bi dopustio potkopati svoje kuće. Zato budite pripravni i vi, jer će Čovječji Sin doći u čas, kada vi i ne slutite.","kn":"t Slijedi sveto evanđelje po Luki (12, 35-40). U ono vrijeme reče Isus svojim učenicima: Neka budu opasani vaši bokovi i upaljene svjetiljke u vašim rukama. A vi sami budite kao oni ljudi, koji očekuju svoga gospodara, kad se vraća sa svadbe, da čim dođe i pokuca, smjesta mu otvore vrata. Blago onim slugama, koje gospodar došav nađe budne. Zaista vam kažem, da će se sam priipasati i posaditi Ih za stol i sam će ih poslužiti. Blago tim slugama, ako ih zateče tako, ako dođe o drugoj ili trećoj straži. Znajte ovo: Kad bi domaćin znao, u koji čas dolazi tat, zaista bi bdio i ne bi dao potkopati svoje kuće. I vi budite spremni, jer u čas, kad vi ne mislite, doći će Sin čovječji.","knRef":"Kniewald 1942, str. 594–595 (snimka 298) (OCR)"},"da7157afd5ffa6f6":{"t":"Ps 118, 32\nTrčim putem tvojih zapovijedi, od veselja mi se širi srce. <i>Aleluja</i>.","v":"aleluia → ∅","kn":"(Ps. 118. 32). Trčao sam Tvojim putevima, kad si raširio srce moje (aleluja).","knRef":"Kniewald 1942, str. 580–581 (snimka 291) (OCR)"},"73b12e60f3d7fddc":{"t":"Umilostivljen pogledaj, molimo, Gospo dine, na ove žrtve, i podaj da nas Duh Sveti raspali onim ognjem, kojim je čudesno prožeo srce blaženog Filipa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, pogledaj umilostivljen na ove žrtve i pođhj, da nas Duh Sveti raspalronim ognjem, kojim je čudesno prozeo^ srce bi. Filipa, po G. n _ u jedinstvu istoga Duha ...","knRef":"Kniewald 1942, str. 580–581 (snimka 291) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"bd083b7934bf71ab":{"t":"Ps 83, 3\nMoje srce i moje tijelo kliču od radosti u Bogu živomu. <i>Aleluja</i>","v":"aleluia → ∅","kn":"(Ps. 83, 3). Srce moje i tijelo moje klikcu Bogu živomu (aleluja).","knRef":"Kniewald 1942, str. 580–581 (snimka 291) (OCR)"},"abd13ba5295fe363":{"t":"<i>Pomolimo se</i>.\nNahranjeni, Gospodine, nebeskom hranom molimo, da po zaslugama i nasljedovanju blaženog Filipa priznavaoca tvoga težimo vazda za onim po čemu doista živimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Nahranjeni, Gospodine, nebeskim sl^- tima, moiimo., da zagovorom i nasljedovanjem bi. Filipa, priznavaoca Tvoga, uvijek za onim težimo, po čemu istinski živimo, po G. n. . ^ ^ u Engleskoj. Sveto je umro 735.","knRef":"Kniewald 1942, str. 580–581 (snimka 291) (OCR)"},"a4837c18d276cbd0":{"t":"Rim 5, 5, Ps 102, 1\n(Rim 5, 5) Ljubav se Božja izlila u našim srcima po Duhu Svetom, koji stanuje u nama. <i>Aleluja</i>, <i>aleluja</i>.\n(Ps 102, 1) Blagoslivljaj, dušo moja, Gospodina! I sve što je u meni sveto ime njegovo.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Rim 5, 5) Ljubav se Božja izlila u našim srcima po Duhu Svetom, koji stanuje u nama, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Rim. 5, 5). Ljubav se Božja izlila u srcima našim., aleluja, po Duhu Svetom, koji nam je dan aleluja, aleluja: (Ps. 102, 1). Blagosivaj, dušo moja' Gospodina, i sve, što je u meni, sveto ime njegovo’. Slava Ocu . . . Ljubav . . . se« dijeli se prva tonzura,.. a onda se«, bez »Prignimo . , a tako i","knRef":"Kniewald 1942, str. 354–355 (snimka 178) (OCR)"},"097eada0f864a592":{"t":"Tuž 1, 13, Ps 38, 4\n<i>Aleluja</i>, <i>aleluja</i>.\n(Tuž 1, 13) S visine je bacio oganj u moje kosti i poučio me. <i>Aleluja</i>.\n(Ps 38, 4) Srce mi se zapalilo, i od razmišljanja moga rasplamsala se vatra. <i>Aleluja</i>.","v":"tren ps → ∅","kn":"Aleluja, aleluja. Iz visina je it^lao oganj u kosti moje i poučio me je aleluja. (Ps. 38, 4) Zapali ^ srce moje u grudima mojim, u mislima se mojim rasplamtio oganj, aleluja.","knRef":"Kniewald 1942, str. 580–581 (snimka 291) (OCR)"},"8e89256a402c701b":{"t":"Ps 118, 32\nTrčim putem tvojih zapovijedi, od veselja mi se širi srce. <i>Aleluja</i>.","kn":"(Ps. 118. 32). Trčao sam Tvojim putevima, kad si raširio srce moje (aleluja).","knRef":"Kniewald 1942, str. 580–581 (snimka 291) (OCR)"},"e3481c16f40c8803":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – On se poslije svojeg uskrsnuća svim svojim učenicima javno ukazao i pred njihovim se očima uzdigao na nebo, da nas učini dionicima svoga božanstva. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje: Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospodinu našem, jer On se poslije svoga uskrsnuća očito ukazao svim svojim učenicima 1 njima se na očigled uzđignuo na nebo, da tako, po njegovom daru, budemo zajedničari Božanstva Njegova. I toga radi pjevamo pjesmu slave Tvoje s anđelima i B arkanđelima, s prijestolima i s gospodstvima, sa svom silom nebeske vojske bez prestanka govoreći:","knRef":"Kniewald 1942, str. 336–337 (snimka 169) (OCR)"},"c2b744acd33e06af":{"t":"Ps 83, 3\nMoje srce i moje tijelo kliču od radosti u Bogu živomu. <i>Aleluja</i>","kn":"(Ps. 83, 3). Srce moje i tijelo moje klikcu Bogu živomu (aleluja).","knRef":"Kniewald 1942, str. 580–581 (snimka 291) (OCR)"}}});
